    const leg = (from, to) => {
      const ord = [[0,1,2],[0,2,1],[1,0,2],[1,2,0],[2,0,1],[2,1,0]][Math.floor(fr(i*19.3+from[0]+to[1]*2.3)*6)%6];
      let cur = from.slice();
