      return cur;
    };
    const mid = leg([bx,hy,hz], [wx,wy,wz]);
    leg(mid, [ex,ey,ez]);
    lines.push({ pts, svc: Math.floor(fr(i*23.1+29)*4)%4, dia: .48 + fr(i*29.3+31)*.42,
      tag: (Math.floor(fr(i*31.7+37)*8)+2)+'"-'+SVCN[Math.floor(fr(i*23.1+29)*4)%4].replace(/[^A-Z]/g,'').slice(0,2)+'-'+(100+Math.floor(fr(i*37.1+41)*880)),
