// ---- sheet border + title block + service legend ----------------------------
const mgn = u*.028;
noFill(); sc(C.anno, 46+24*anno); strokeWeight(Math.max(.8,u*.0022));
rect(mgn, mgn, width-mgn*2, height-mgn*2);
sc(C.anno, 22+16*anno); strokeWeight(Math.max(.5,u*.0009));
rect(mgn*1.7, mgn*1.7, width-mgn*3.4, height-mgn*3.4);
if (anno > .08){
  textFont('monospace'); noStroke(); textSize(Math.max(7,u*.0135));
