  noStroke(); fc(C.anno, 90);
  text('PIPING ISOMETRIC - UNIT '+(10+(sd%80)), bx-u*.012, by-u*.039);
  text((pid?'P&ID SYMBOLS':'SPOOL VIEW')+'   '+lines.length+' LINES   SEED '+sd, bx-u*.012, by-u*.013);
  // service legend
